package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** A grade's rate as the screen shows it; the percent always has two decimals; from is null from the start, to null with no end. */
    public record RateView(String grade, LocalDate from, LocalDate to, String pct) {
        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getFromDate(), rate.getToDate(), rate.getPct().setScale(2).toPlainString());
        }
    }

    /** A percent of 0.00 or more, with at most two decimals, from a date (none: from the beginning of time) through a date (none: no end). */
    public record RateRequest(@NotNull @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String pct, LocalDate from, LocalDate to) {

        BigDecimal pctValue() {
            return new BigDecimal(pct).setScale(2);
        }
    }

    private final RateService service;

    public RateController(RateService service) {
        this.service = service;
    }

    @GetMapping
    public List<RateView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId).stream().map(RateView::of).toList();
    }

    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RateRequest request) {
        return RateView.of(service.set(sheetId, user, grade, request.from(), request.to(), request.pctValue()));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's rates for each grade, each from a date (or from the beginning of time): set one grade
 * and from-date at a time, replacing any rate it had. A date's rate is the one with the latest
 * from-date on or before it.
 */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository log;
    private final SheetRepository sheets;
    private final RollupService rollup;
    private final Audit audit;

    public RateService(RateRepository rates, RateLogRepository log, SheetRepository sheets, RollupService rollup,
            Audit audit) {
        this.rates = rates;
        this.log = log;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
    }

    /** The grade's rate on the date: the one with the latest from-date on or before it, if any and not ended. */
    @Transactional(readOnly = true)
    public Optional<Rate> on(String sheetId, String grade, LocalDate date) {
        return Rate.inForce(rates.findBySheetIdAndGrade(sheetId, grade), date);
    }

    /**
     * The sheet's rates by grade as they stood at the end of the date: of those set while the sheet's
     * today was on or before it, the last set for each grade and from-date.
     */
    @Transactional(readOnly = true)
    public Map<String, List<Rate>> asOf(String sheetId, LocalDate date) {
        Map<String, Map<Optional<LocalDate>, Rate>> then = new LinkedHashMap<>();
        for (RateLog line : log.findBySheetIdOrderByIdAsc(sheetId)) {
            if (!line.setBy(date)) continue;
            then.computeIfAbsent(line.getGrade(), g -> new LinkedHashMap<>())
                    .put(Optional.ofNullable(line.getFromDate()), line.toRate());
        }
        Map<String, List<Rate>> byGrade = new LinkedHashMap<>();
        then.forEach((grade, rates) -> byGrade.put(grade, new ArrayList<>(rates.values())));
        return byGrade;
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (to != null && from != null && to.isBefore(from)) throw new RateDatesException();
        // Lock the sheet so two users setting the same grade and from-date at once replace one rate.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Optional<Rate> existing = from == null
                ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from);
        Rate rate = existing.orElseGet(() -> new Rate(sheetId, grade, from, to, pct));
        rate.setPct(pct);
        rate.setToDate(to);
        Rate saved = rates.saveAndFlush(rate);
        log.saveAndFlush(new RateLog(saved, today));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user.strip()
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().setScale(2).toPlainString()
                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : "")
                + (saved.getToDate() != null ? " to=" + saved.getToDate() : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateRepository extends JpaRepository<Rate, Long> {

    List<Rate> findBySheetIdOrderByGradeAscFromDateAsc(String sheetId);

    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    Optional<Rate> findBySheetIdAndGradeAndFromDateIsNull(String sheetId, String grade);

    Optional<Rate> findBySheetIdAndGradeAndFromDate(String sheetId, String grade, LocalDate fromDate);
}
import { HttpClient } from '@angular/common/http';
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Rate {
  grade: string;
  /** The first date (yyyy-mm-dd) it applies on; null when it applies from the beginning of time. */
  from: string | null;
  /** The last date (yyyy-mm-dd) it applies on; null when it has no end. */
  to: string | null;
  /** A percent, always two decimals, e.g. "12.50". */
  pct: string;
}

export const GRADES = ['A', 'B', 'C'];

/** Shown for a due that has no rate. */
export const NA = 'n/a';

/** Cents times a percent (two decimals), divided by 100, rounded half to even (or half up) to whole cents. */
export function dueCents(amountCents: number, pct: string, halfUp = false): number {
  const [whole, frac = ''] = pct.split('.');
  const pctHundredths = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  // Rounded on the size of the product, so a negative due rounds as its positive would.
  const sign = amountCents < 0 ? -1 : 1;
  const product = BigInt(Math.abs(amountCents)) * pctHundredths;
  const quotient = product / 10000n;
  const remainder = product % 10000n;
  const up = remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n));
  return sign * Number(up ? quotient + 1n : quotient);
}

/** Of one grade's rates, the percent in force on a date (the latest from-date on or before it, unless the
 *  date is after that rate's to-date), or null. */
export function pctOn(rates: Rate[], date: string): string | null {
  return rateOn(rates, date)?.pct ?? null;
}

/** Of one grade's rates, the one in force on a date (as `pctOn` has it), or null. */
export function rateOn(rates: Rate[], date: string): Rate | null {
  // No from-date sorts as '', before every date.
  let best: Rate | null = null;
  for (const r of rates) {
    const from = r.from ?? '';
    if (from <= date && (best === null || from > (best.from ?? ''))) best = r;
  }
  if (best === null || (best.to !== null && date > best.to)) return null;
  return best;
}

// The sheet's rates, each for a grade from a from-date (or from the start), with one form to set
// a grade's rate from a date (and through a date, if it ends); and per grade, the rate in force on the sheet's today.
@Component({
  selector: 'app-rates',
  imports: [ReactiveFormsModule],
